To convert markdown formatted text to HTML in C++, you can use a library like `commonmark` or `pugixml`. However, for simplicity, I'll demonstrate a basic approach using a custom function that handles some common markdown to HTML conversions. This example will not cover all markdown features but will give you a starting point.

First, you need to include the necessary headers and define the function:

```cpp
#include <iostream>
#include <string>
#include <sstream>

// Function to convert markdown to HTML
std::string markdownToHtml(const std::string& markdown) {
    std::stringstream ss;
    // Simple conversion rules
    ss << "<html><body>";
    for (size_t i = 0; i < markdown.length(); ++i) {
        if (markdown[i] == '\n') {
            ss << "<br>";
        } else if (markdown[i] == '#') {
            ss << "<h1>";
            while (i + 1 < markdown.length() && markdown[i + 1] == '#') {
                ++i;
            }
            ss << markdown.substr(++i, i - (markdown.find('#', i) + 1)) << "</h1>";
        } else if (markdown[i] == '*') {
            ss << "<em>";
            while (i + 1 < markdown.length() && markdown[i + 1] == '*') {
                ++i;
            }
            ss << markdown.substr(++i, i - (markdown.find('*', i) + 1)) << "</em>";
        } else {
            ss << markdown[i];
        }
    }
    ss << "</body></html>";
    return ss.str();
}

int main() {
    std::string markdown = "# Header\n*Italic* text\nAnother line";
    std::string html = markdownToHtml(markdown);
    std::cout << html << std::endl;
    return 0;
}
```

### Explanation:
1. **Function Definition**: The `markdownToHtml` function takes a `std::string` containing markdown text and returns a `std::string` containing HTML.
2. **Stream Manipulation**: We use a `std::stringstream` to build the HTML string.
3. **Basic Conversion Rules**:
   - Convert a newline (`\n`) to a `<br>` tag.
   - Convert a `#` followed by any number of `#` to an `<h1>` tag.
   - Convert a `*` followed by any number of `*` to an `<em>` tag.
4. **Main Function**: The `main` function demonstrates how to use the `markdownToHtml` function.

### Limitations:
- This function only handles a few basic markdown features.
- It does not handle nested markdown elements or more complex markdown syntax.
- For a full-featured markdown to HTML converter, consider using a library like `commonmark` or `pandoc`.

### Compilation:
To compile this code, you can use a C++ compiler like `g++`:

```sh
g++ -o markdown_to_html markdown_to_html.cpp
./markdown_to_html
```

This will output the HTML representation of the markdown text.

Creating a smooth Snake game in C that uses images for animation involves several steps. You'll need to use a graphics library that supports image handling and window management. One popular choice is SDL (Simple DirectMedia Layer), which is cross-platform and widely used for such tasks.

Below is a step-by-step guide to creating a basic Snake game using SDL in C. This example will use images for the snake and the food.

### Step 1: Install SDL
First, you need to install SDL. You can do this using your package manager or by downloading the source code and compiling it.

For example, on Ubuntu, you can install SDL with:
```sh
sudo apt-get install libsdl2-dev
```

### Step 2: Set Up Your Project
Create a new directory for your project and set up your `main.c` file.

### Step 3: Write the Code

Here's a basic implementation of the Snake game using SDL:

```c
#include <SDL2/SDL.h>
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define SCREEN_WIDTH 640
#define SCREEN_HEIGHT 480
#define BLOCK_SIZE 20

typedef struct {
    int x, y;
} Point;

typedef struct {
    Point head;
    Point tail;
    int length;
} Snake;

typedef enum {
    UP, DOWN, LEFT, RIGHT
} Direction;

void init_snake(Snake *snake) {
    snake->head.x = SCREEN_WIDTH / 2;
    snake->head.y = SCREEN_HEIGHT / 2;
    snake->tail.x = snake->head.x - BLOCK_SIZE;
    snake->tail.y = snake->head.y;
    snake->length = 2;
}

void move_snake(Snake *snake, Direction dir) {
    switch (dir) {
        case UP:
            snake->head.y -= BLOCK_SIZE;
            break;
        case DOWN:
            snake->head.y += BLOCK_SIZE;
            break;
        case LEFT:
            snake->head.x -= BLOCK_SIZE;
            break;
        case RIGHT:
            snake->head.x += BLOCK_SIZE;
            break;
    }

    // Update tail position
    snake->tail.x = snake->head.x - (snake->length - 1) * BLOCK_SIZE;
    snake->tail.y = snake->head.y;
}

void draw_snake(SDL_Renderer *renderer, Snake *snake) {
    SDL_Rect rect = {snake->head.x, snake->head.y, BLOCK_SIZE, BLOCK_SIZE};
    SDL_RenderCopy(renderer, g_snake_texture, NULL, &rect);

    rect.x = snake->tail.x;
    rect.y = snake->tail.y;
    SDL_RenderCopy(renderer, g_snake_texture, NULL, &rect);
}

void draw_food(SDL_Renderer *renderer, SDL_Texture *food_texture, int x, int y) {
    SDL_Rect rect = {x, y, BLOCK_SIZE, BLOCK_SIZE};
    SDL_RenderCopy(renderer, food_texture, NULL, &rect);
}

int main(int argc, char *argv[]) {
    // Initialize SDL
    if (SDL_Init(SDL_INIT_VIDEO) < 0) {
        printf("SDL could not initialize! SDL_Error: %s\n", SDL_GetError());
        return -1;
    }

    // Create window
    SDL_Window *window = SDL_CreateWindow("Snake Game", SDL_WINDOWPOS_UNDEFINED, SDL_WINDOWPOS_UNDEFINED, SCREEN_WIDTH, SCREEN_HEIGHT, SDL_WINDOW_SHOWN);
    if (!window) {
        printf("Window could not be created! SDL_Error: %s\n", SDL_GetError());
        SDL_Quit();
        return -1;
    }

    // Create renderer
    SDL_Renderer *renderer = SDL_CreateRenderer(window, -1, SDL_RENDERER_ACCELERATED);
    if (!renderer) {
        printf("Renderer could not be created! SDL_Error: %s\n", SDL_GetError());
        SDL_DestroyWindow(window);
        SDL_Quit();
        return -1;
    }

    // Load textures
    SDL_Surface *snake_surface = SDL_LoadBMP("snake.bmp");
    if (!snake_surface) {
        printf("Failed to load snake.bmp! SDL_image Error: %s\n", SDL_GetError());
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return -1;
    }

    g_snake_texture = SDL_CreateTextureFromSurface(renderer, snake_surface);
    SDL_FreeSurface(snake_surface);

    SDL_Surface *food_surface = SDL_LoadBMP("food.bmp");
    if (!food_surface) {
        printf("Failed to load food.bmp! SDL_image Error: %s\n", SDL_GetError());
        SDL_DestroyTexture(g_snake_texture);
        SDL_DestroyRenderer(renderer);
        SDL_DestroyWindow(window);
        SDL_Quit();
        return -1;
    }

    g_food_texture = SDL_CreateTextureFromSurface(renderer, food_surface);
    SDL_FreeSurface(food_surface);

    // Initialize snake
    Snake snake;
    init_snake(&snake);

    // Initialize direction
    Direction dir = RIGHT;

    // Main loop flag
    bool running = true;

    // Event handler
    SDL_Event e;

    // Game loop
    while (running) {
        while (SDL_PollEvent(&e) != 0) {
            if (e.type == SDL_QUIT) {
                running = false;
            } else if (e.type == SDL_KEYDOWN) {
                switch (e.key.keysym.sym) {
                    case SDLK_UP:
                        if (dir != DOWN) {
                            dir = UP;
                        }
                        break;
                    case SDLK_DOWN:
                        if (dir != UP) {
                            dir = DOWN;
                        }
                        break;
                    case SDLK_LEFT:
                        if (dir != RIGHT) {
                            dir = LEFT;
                        }
                        break;
                    case SDLK_RIGHT:
                        if (dir != LEFT) {
                            dir = RIGHT;
                        }
                        break;
                }
            }
        }

        // Move snake
        move_snake(&snake, dir);

        // Clear screen
        SDL_SetRenderDrawColor(renderer, 0, 0, 0, 255);
        SDL_RenderClear(renderer);

        // Draw snake and food
        draw_snake(renderer, &snake);
        draw_food(renderer, g_food_texture, 100, 100);

        // Update screen
        SDL_RenderPresent(renderer);

        // Cap the frame rate
        SDL_Delay(100);
    }

    // Clean up
    SDL_DestroyTexture(g_snake_texture);
    SDL_DestroyTexture(g_food_texture);
    SDL_DestroyRenderer(renderer);
    SDL_DestroyWindow(window);
    SDL_Quit();

    return 0;
}
```

### Step 4: Create the Images
You need to create two images:
- `snake.bmp`: This will be the image for the snake.
- `food.bmp`: This will be the image for the food.

### Step 5: Compile and Run
Compile your code using a C compiler that supports SDL. For example, using `gcc`:

```sh
gcc -o snake main.c -lSDL2
```

Run the compiled executable:

```sh
./snake
```

### Notes:
- Ensure that the images are in the same directory as your executable or provide the correct path to the images.
- This is a basic implementation. You can add more features like collision detection, scoring, and game over conditions.
- Make sure to handle errors and edge cases in a production-quality game.

This should give you a good starting point for creating a smooth Snake game using SDL in C.

